#include <cstring>
#include <array>
#include <fstream>
#include <iostream>
#include "backends/cpu/cpu_backend.hpp"

__declspec(noinline) void kernel(const float* r, size_t stride, const float* x,
                                 const float* y, const float* z, size_t n,
                                 float* a, float* b, float* c) {
    backend::CpuBackend::dot_f32_x4x3(r, stride, x, y, z, n, a, b, c);
}

int main(int argc, char** argv) {
    if (argc != 2) return 2;
    std::ofstream out(argv[1], std::ios::binary);
    size_t count = 0;
    for (size_t n : std::array<size_t, 19>{0,1,2,7,8,9,15,16,17,31,32,33,127,128,129,1023,1024,1025,2048}) {
        for (size_t offset = 0; offset < 8; ++offset) {
            const size_t stride = n + 13;
            std::vector<float> rows(4 * stride + 8), inputs(3 * stride + 8);
            for (size_t i = 0; i < rows.size(); ++i)
                rows[i] = float(int((i * 1471 + 7) % 65521) - 32760) / 317.0f;
            for (size_t i = 0; i < inputs.size(); ++i)
                inputs[i] = float(int((i * 769 + 23) % 32749) - 16374) / 523.0f;
            const float* r = rows.data() + offset;
            const float* x = inputs.data() + offset;
            float actual[12];
            kernel(r, stride, x, x + stride, x + 2 * stride, n, actual, actual + 4, actual + 8);
            for (size_t c = 0; c < 3; ++c) for (size_t k = 0; k < 4; ++k) {
                float lanes[8] = {};
                size_t j = 0;
                for (; j + 8 <= n; j += 8)
                    for (size_t lane = 0; lane < 8; ++lane)
                        lanes[lane] = std::fma(r[k * stride + j + lane], x[c * stride + j + lane], lanes[lane]);
                float v = lanes[0];
                for (size_t lane = 1; lane < 8; ++lane) v += lanes[lane];
                for (; j < n; ++j) v += r[k * stride + j] * x[c * stride + j];
                if (std::memcmp(&v, &actual[c * 4 + k], sizeof(float))) {
                    std::cerr << "mismatch n=" << n << " offset=" << offset << " row=" << k << " col=" << c << '\n';
                    return 3;
                }
                ++count;
            }
            out.write(reinterpret_cast<const char*>(actual), sizeof(actual));
        }
    }
    std::cout << count << " exact scalar-FMA outputs\n";
    return out ? 0 : 4;
}

