#include <fstream>
#include <iostream>
#include <iomanip>
#include "inference/perplexity.hpp"
int main(int argc,char** argv) {
    if(argc!=3)return 2;
    auto weights=gguf::read_gguf(argv[1]);infer::Model model(weights);model.set_threads(6);
    std::ifstream in(argv[2]);std::vector<uint32_t> ids;uint32_t id;while(in>>id)ids.push_back(id);
    if(ids.size()!=247)return 3;
    for(auto flags: {std::pair<int,int>{0,0},{64,0},{64,2},{123,0}}) {
        auto v=infer::perplexity(model,ids,flags.first,flags.second);
        std::cout<<std::setprecision(17)<<"{\"ctx\":"<<flags.first<<",\"max_chunks\":"<<flags.second
            <<",\"used\":"<<v.used_tokens<<",\"scored\":"<<v.scored_tokens<<",\"chunks\":"<<v.chunks
            <<",\"mean_nll\":"<<v.mean_nll()<<",\"ppl\":"<<std::exp(v.mean_nll())<<"}\n"<<std::flush;
    }
}

